events.onChange:
{(next) => {
          if (submitting || switching) return;
          editRevision.current += 1;
          setFieldErrors((current) => current.filter((error) => !error.field || Object.is(next[error.field], workflowValues[error.field])));
          setWorkflowValues(next);
          setPrompt(String(next.prompt ?? ''));
          setResolution(String(next.resolution ?? RESOLUTION_OPTIONS[0]));
          setDuration(String(next.duration ?? 5));
          setSeed(String(next.seed ?? ''));
        }}

events.onPress:
{() => {
        if (lock.current) return; lock.current = true; setBusy(true);
        void creativeBudget().list().then(async rows => { for (const row of rows) if (row.project_id === selected && row.revoked_at == null) await creativeBudget().revoke(row.id); setNotice('当前项目授权已撤销'); }).catch(() => setNotice('撤销失败')).finally(() => { lock.current = false; setBusy(false); });
      }}

{()=>{void(async()=>{
      setError('');if(status.playing){player.pause();return;}
      if(status.didJustFinish||(status.duration>0&&status.currentTime>=status.duration))await player.seekTo(0);
      player.play();
    })().catch(()=>setError('无法播放，请保存原件后使用其他播放器打开。'));}}

